SELECT id AS group_id, name, sort_order, version
FROM groups
WHERE space_id = #{spaceId} AND event_id = #{eventId}
AND id = #{groupId}
ORDER BY sort_order, id

SELECT p.id AS participant_id, p.name, nullif(btrim(coh.value ->> 'text'), '') AS cohort, gen.value ->> 'optionId' AS gender_option_id, (SELECT o ->> 'label' FROM jsonb_array_elements(gen.config -> 'options') o WHERE o ->> 'optionId' = gen.value ->> 'optionId' LIMIT 1) AS gender_label, (att.config IS NOT NULL) AS attendance_asked, att.value ->> 'optionId' AS attendance_option_id, coalesce( nullif(btrim(mid.value ->> 'text'), ''), (SELECT o ->> 'label' FROM jsonb_array_elements(mid.config -> 'options') o WHERE o ->> 'optionId' = mid.value ->> 'optionId' LIMIT 1)) AS middle_group, coalesce( nullif(btrim(cel.value ->> 'text'), ''), (SELECT o ->> 'label' FROM jsonb_array_elements(cel.config -> 'options') o WHERE o ->> 'optionId' = cel.value ->> 'optionId' LIMIT 1)) AS cell, mid.config::text AS middle_group_config, mid.value::text AS middle_group_answer, cel.config::text AS cell_config, cel.value::text AS cell_answer, ga.group_id, coalesce(ga.leader, false) AS leader, mea.value::text AS meals_answer, arr.value::text AS arrival_answer, dep.value::text AS departure_answer FROM participants p JOIN LATERAL () app ON true LEFT JOIN LATERAL (
) coh ON true LEFT JOIN LATERAL (
) gen ON true LEFT JOIN LATERAL (
) att ON true LEFT JOIN LATERAL (
) mid ON true LEFT JOIN LATERAL (
) cel ON true LEFT JOIN LATERAL (
) mea ON true LEFT JOIN LATERAL (
) arr ON true LEFT JOIN LATERAL (
) dep ON true LEFT JOIN group_assignments ga ON ga.space_id = p.space_id AND ga.event_id = p.event_id AND ga.participant_id = p.id WHERE p.space_id = #{spaceId} AND p.event_id = #{eventId} ORDER BY p.name COLLATE "C", p.id

