) coh ON true LEFT JOIN group_assignments ga ON ga.space_id = p.space_id AND ga.event_id = p.event_id AND ga.participant_id = p.id WHERE p.space_id = #{spaceId} AND p.event_id = #{eventId}
AND p.id IN
